import subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
rows=[]
for b in branches:
    out=subprocess.check_output(['git','log',f'origin/friend/{b}','--format=%H%x1f%ci%x1f%B%x1e'], text=True)
    for rec in out.split('\x1e'):
        if not rec.strip(): continue
        parts=rec.split('\x1f',2)
        sha,ci,body=parts[0],parts[1],parts[2]
        if 'Friend-Message: 1' not in body: continue
        ep=None; speaker=None
        for line in body.splitlines():
            if line.startswith('Episode:'): ep=line.split(':',1)[1].strip()
            if line.startswith('Speaker:'): speaker=line.split(':',1)[1].strip()
        if ep=='S05/E24':
            rows.append((ci,sha,b,speaker,body.strip().split('\n')[-1]))
print('count',len(rows))
for r in sorted(rows):
    print(r[0], r[3], r[2], r[1][:12], '|', r[4][:90])
